def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    import subprocess
    from concurrent.futures import ThreadPoolExecutor
    import os

    def _chunkify(varargs, chunk_size):
        for i in range(0, len(varargs), chunk_size):
            yield varargs[i:i + chunk_size]

    def _run_command(chunk):
        try:
            full_cmd = cmd + tuple(chunk)
            if color and os.name != 'nt':
                process = subprocess.run(full_cmd, check=False, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=False, shell=False, bufsize=0, universal_newlines=False, preexec_fn=os.setsid)
            else:
                process = subprocess.run(full_cmd, check=False, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=False, shell=False, bufsize=0, universal_newlines=False)
            return process.returncode, process.stdout + process.stderr
        except Exception as e:
            return -1, str(e).encode()

    chunk_size = _max_length // (sum(len(arg) for arg in cmd) + len(cmd) - 1)
    if chunk_size <= 0:
        raise ValueError("Max length is too small to accommodate the base command")

    results = []
    with ThreadPoolExecutor(max_workers=target_concurrency) as executor:
        futures = [executor.submit(_run_command, chunk) for chunk in _chunkify(varargs, chunk_size)]
        for future in futures:
            results.append(future.result())

    final_returncode = 0
    final_output = b''
    for returncode, output in results:
        final_returncode |= returncode  # bitwise OR to combine return codes
        final_output += output
    return final_returncode, final_output

