def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    import os
    import sys

    if os.name == 'nt' and cmd:
        try:
            with open(cmd[0], 'r', encoding='utf-8') as file:
                first_line = file.readline().strip()
                if first_line.startswith('#!'):
                    shebang = first_line[2:].strip()
                    interpreter = shebang.split()[0]
                    if os.path.exists(interpreter):
                        args = shebang.split()[1:]
                        return (interpreter, *args, *cmd[1:])
        except (FileNotFoundError, PermissionError):
            pass
    return cmd

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    import sys
    import os

    if sys.platform == "win32" and cmd:
        try:
            with open(cmd[0], 'r') as file:
                first_line = file.readline().strip()
                if first_line.startswith('#!'):
                    shebang_args = first_line[2:].split()
                    if shebang_args[0].lower() == 'python':
                        # Replace the script with the python executable and the script itself
                        script = cmd[0]
                        new_cmd = [sys.executable] + shebang_args[1:] + [script] + list(cmd[1:])
                        # Convert to short paths to avoid issues with long paths
                        new_cmd = [os.path.normpath(os.path.abspath(path)) for path in new_cmd]
                        return tuple(new_cmd)
        except FileNotFoundError:
            pass
        except Exception as e:
            print(f"An error occurred: {e}", file=sys.stderr)

    return cmd

