    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    import sys
    import os

    if sys.platform != 'win32':
        return cmd

    if not cmd:
        return cmd

    script = cmd[0]
    if not os.path.isfile(script):
        return cmd

    with open(script, 'r', encoding='utf-8') as file:
        first_line = file.readline().strip()
        if first_line.startswith('#!'):
            shebang_args = first_line[2:].strip().split()
            if shebang_args and os.path.basename(shebang_args[0]).lower() in ('python', 'python.exe', 'python3', 'python3.exe'):
                shebang_args = [sys.executable] + shebang_args[1:]
                return tuple(shebang_args + list(cmd[1:]))

    return cmd

