    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    import functools
    import time

    def decorator(func):
        cache = functools.lru_cache(maxsize=maxsize, typed=typed)

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, tuple(kwargs.items())) if typed else args + tuple(kwargs.values())
            value, timestamp = cache.get(key, (None, -float('inf')))
            if timer() - timestamp > ttl:
                value = func(*args, **kwargs)
                cache[key] = (value, timer())
            return value

