def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    try:
        # Create a set to track seen classes
        seen = set()
        # Create a list to store the minimal bases
        minimal = []

        # Iterate over the classes in reverse order
        for cls in reversed(classes):
            # If the class is not a subclass of any previously seen class, add it
            if not any(issubclass(seen_class, cls) for seen_class in seen):
                minimal.append(cls)
                seen.add(cls)

        # Return the minimal bases in their original order
        return [cls for cls in classes if cls in seen][::-1]
    except TypeError:
        raise ValueError("All elements in the input list must be classes.")
    except Exception as e:
        raise RuntimeError(f"An unexpected error occurred: {e}")

