def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    if not isinstance(bins, (list, tuple)) or not isinstance(edges, (list, tuple)):
        raise ValueError("Bins and edges must be lists or tuples.")
    if len(bins) != len(edges) - 1:
        raise ValueError("The number of bins must be one less than the number of edges.")

    integral_value = 0.0
    for i in range(len(bins)):
        if not (isinstance(bins[i], (int, float)) and isinstance(edges[i], (int, float)) and isinstance(edges[i + 1], (int, float))):
            raise ValueError("Bins and edges must contain numeric values only.")
        width = edges[i + 1] - edges[i]
        if width < 0:
            raise ValueError("Edges must be in non-decreasing order.")
        integral_value += bins[i] * width

    return integral_value

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    if not isinstance(bins, (list, tuple)) or not isinstance(edges, (list, tuple)):
        raise ValueError("bins and edges must be lists or tuples.")

    if len(bins) + 1 != len(edges):
        raise ValueError("The number of edges must be one more than the number of bins.")

    try:
        integral_value = sum(b * (e2 - e1) for b, e1, e2 in zip(bins, edges, edges[1:]))
    except TypeError:
        raise ValueError("All elements in bins and edges must be numbers.")

    return integral_value

