            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re
    from collections.abc import Iterable

    key_regex = re.compile(r'^[a-zA-Z0-9_-]+$')
    errors = []

    for key, value in labels.items():
        # Validate key
        if not isinstance(key, str) or not key_regex.match(key):
            if isinstance(key, bool):
                key = str(key)
            elif not isinstance(key, str):
                key = repr(key)
            errors.append({key: f"Label key '{key}' does not match the regex '{key_regex.pattern}'"})

        # Validate value
        if isinstance(value, str):
            continue
        elif isinstance(value, Iterable) and not isinstance(value, (str, bytes)):
            for item in value:
                if not isinstance(item, str):
                    if isinstance(item, bool):
                        item = str(item)
                    elif not isinstance(item, str):
                        item = repr(item)
                    errors.append({item: 'expected string or bytes-like object'})
        else:
            if isinstance(value, bool):
                value = str(value)
            elif not isinstance(value, str):
                value = repr(value)
            errors.append({value: 'expected string or bytes-like object'})

    if errors:
        class ValidationError(Exception):
            def __init__(self, messages):
                self.messages = messages
                super().__init__(str(messages))

        raise ValidationError(errors)

