def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os
    from collections import defaultdict

    try:
        if not os.path.isdir(folder):
            raise ValueError(f"The provided path '{folder}' is not a valid directory.")

        package_data = defaultdict(list)

        for filename in os.listdir(folder):
            if filename.endswith('.xml'):
                base_name = os.path.splitext(filename)[0]
                package_data[base_name].append(os.path.join(folder, filename))

        return dict(package_data)

    except Exception as e:
        print(f"An error occurred: {e}")
        return {}

def _eval_file(prefix, filename, file_folder):
    """
    Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.

    Identifica o tipo de arquivo do pacote e atualiza `packages` com o tipo e
    o endereço do arquivo em análise.

    Parameters
    ----------
    prefix : str
        nome do arquivo XML sem extensão
    filename : str
        filename
    file_folder : str
        file folder

    Returns
    -------
    dict
    """
    try:
        file_path = f"{file_folder}/{filename}"
        if prefix in filename:
            if "rendition" in filename:
                return {"type": "rendition", "path": file_path}
            elif "asset" in filename:
                return {"type": "asset", "path": file_path}
        return {"type": "unknown", "path": file_path}
    except Exception as e:
        return {"type": "error", "message": str(e)}

