def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::
        A & (A | B) = A, A | (A & B) = A

    Negative absorption::
        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    if not isinstance(args, list):
        raise ValueError("args must be a list of expressions")

    new_args = []
    for i in range(len(args)):
        expr = args[i]
        if isinstance(expr, tuple) and len(expr) == 3:
            op, left, right = expr
            if op == '&':
                if isinstance(right, tuple) and right[0] == '|':
                    if left == right[1] and isinstance(right[2], tuple) and right[2][0] == '~' and right[2][1] == left:
                        new_args.append((op, left, right[2][1]))  # A & (~A | B) = A & B
                    elif left == right[1]:
                        new_args.append(left)  # A & (A | B) = A
                    else:
                        new_args.append(expr)
                elif isinstance(right, tuple) and right[0] == '&':
                    if left == right[1]:
                        new_args.append(left)  # A & (A & B) = A
                    else:
                        new_args.append(expr)
                else:
                    new_args.append(expr)
            elif op == '|':
                if isinstance(right, tuple) and right[0] == '&':
                    if left == right[1] and isinstance(right[2], tuple) and right[2][0] == '~' and right[2][1] == left:
                        new_args.append((op, left, right[2][1]))  # A | (~A & B) = A | B
                    elif left == right[1]:
                        new_args.append(left)  # A | (A & B) = A
                    else:
                        new_args.append(expr)
                elif isinstance(right, tuple) and right[0] == '|':
                    if left == right[1]:
                        new_args.append(left)  # A | (A | B) = A
                    else:
                        new_args.append(expr)
                else:
                    new_args.append(expr)
            else:
                new_args.append(expr)
        else:
            new_args.append(expr)
    return new_args

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    from collections import namedtuple
    Expression = namedtuple('Expression', ['op', 'left', 'right'])

    def simplify(expr):
        if isinstance(expr, Expression):
            if expr.op == '&':
                if expr.right == Expression('|', expr.left, any):
                    return expr.left  # A & (A | B) = A
                elif expr.right == Expression('&', Expression('~', expr.left, None), any):
                    return Expression('&', expr.left, expr.right.right)  # A & (~A | B) = A & B
            elif expr.op == '|':
                if expr.right == Expression('&', expr.left, any):
                    return expr.left  # A | (A & B) = A
                elif expr.right == Expression('|', Expression('~', expr.left, None), any):
                    return Expression('|', expr.left, expr.right.right)  # A | (~A & B) = A | B
        return expr

    simplified_args = []
    for arg in args:
        simplified_args.append(simplify(arg))

    return simplified_args

