    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    from copy import deepcopy

    def apply_absorption(expr):
        if isinstance(expr, tuple) and len(expr) == 3:
            op, left, right = expr
            if op == '&':
                if right == (('|', left, deepcopy(left)),):
                    return left
                elif isinstance(right, tuple) and len(right) == 3 and right[0] == '|' and right[1] == ('~', deepcopy(left),):
                    return ('&', left, right[2])
            elif op == '|':
