def _fromutc(self, dt):
    """
    Given a timezone-aware datetime in a given timezone, calculates a
    timezone-aware datetime in a new timezone.

    Since this is the one time that we *know* we have an unambiguous
    datetime object, we take this opportunity to determine whether the
    datetime is ambiguous and in a "fold" state (e.g. if it's the first
    occurrence, chronologically, of the ambiguous datetime).

    :param dt:
        A timezone-aware :class:`datetime.datetime` object.
    """
    if dt is None or dt.tzinfo is None:
        raise ValueError("dt must be a timezone-aware datetime object")

    # Convert the given dt to UTC
    dt_utc = dt.astimezone(datetime.timezone.utc)

    # Localize the UTC time to the target timezone
    dt_local = self.localize(dt_utc, is_dst=None)

    # Check if the datetime is ambiguous in the target timezone
    if self._isdst(dt_local.utcoffset()) != self._isdst(dt_local.utcoffset(dt_local.replace(fold=not dt_local.fold))):
        # Determine if the given dt is in the first fold occurrence
        dt_first_fold = self.localize(dt_utc, is_dst=True) if self._isdst(dt_local.utcoffset()) else self.localize(dt_utc, is_dst=False)
        dt_second_fold = self.localize(dt_utc, is_dst=False) if self._isdst(dt_local.utcoffset()) else self.localize(dt_utc, is_dst=True)
        if dt_local == dt_first_fold:
            return dt_local.replace(fold=True)
        elif dt_local == dt_second_fold:
            return dt_local.replace(fold=False)
        else:
            raise ValueError("dt is ambiguous but does not match either fold occurrence")
    else:
        return dt_local

def normalized(self):
    """
    Return a version of this object represented entirely using integer
    values for the relative attributes.

    >>> relativedelta(days=1.5, hours=2).normalized()
    relativedelta(days=+1, hours=+14)

    :return:
        Returns a :class:`dateutil.relativedelta.relativedelta` object.
    """
    from dateutil.relativedelta import relativedelta

    # Extract all attributes and their values
    attrs = {attr: getattr(self, attr) for attr in self._fields}

    # Normalize the attributes
    for attr, value in attrs.items():
        if not isinstance(value, int):
            if attr in ['days', 'months', 'years']:
                remainder = 0
                if attr == 'days':
                    remainder = int((value % 1) * 24)
                    attrs[attr] = int(value)
                    attrs['hours'] += remainder
                elif attr == 'months':
                    remainder = int((value % 1) * 30)  # Approximation
                    attrs[attr] = int(value)
                    attrs['days'] += remainder
                elif attr == 'years':
                    remainder = int((value % 1) * 12)
                    attrs[attr] = int(value)
                    attrs['months'] += remainder
            elif attr in ['hours', 'minutes', 'seconds']:
                remainder = int((value % 1) * 60)
                attrs[attr] = int(value)
                attrs[next_field[attr]] += remainder

    # Create a new relativedelta object with normalized values
    return relativedelta(**attrs)

# Mapping of fields for calculating remainders
next_field = {
    'hours': 'minutes',
    'minutes': 'seconds',
}

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    try:
        import sys
        if sys.version_info[0] == 2:
            return map(lambda x: x.encode('ascii') if isinstance(x, unicode) else x, namefunc())
        else:
            return namefunc()
    except NameError:
        return namefunc()  # In Python 3, unicode is not defined, so we just return the result of namefunc()

