def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    try:
        # Split the version into major and minor components
        major, minor = map(int, version.split('.'))
        # Increment the minor version
        minor += 1
        # Format the new version, maintaining zero-padding if present
        if version[0] == '0':
            return f"0{major}.{minor:02d}"
        else:
            return f"{major}.{minor}"
    except (ValueError, IndexError):
        raise ValueError("Invalid version format. Expected format: 'major.minor'")

