    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not isinstance(version_dirs, list):
        raise TypeError("version_dirs must be a list of version directory names.")

    root_inventory = {}
    try:
        with open(os.path.join(self.root_dir, 'inventory.json'), 'r') as f:
            root_inventory = json.load(f)
    except FileNotFoundError:
        raise FileNotFoundError("Root inventory not found.")
    except json.JSONDecodeError:
        raise ValueError("Root inventory is not a valid JSON file.")

    content_digests = {}

    for version in version_dirs:
        version_path = os.path.join(self.root_dir, version)
        inventory_path = os.path.join(version_path, 'inventory.json')

        if not os.path.exists(version_path):
            raise FileNotFoundError(f"Version directory {version} does not exist.")

        if not os.path.exists(inventory_path):
            raise FileNotFoundError(f"Inventory for version {version} does not exist.")

        try:
            with open(inventory_path, 'r') as f:
                version_inventory = json.load(f)
        except json.JSONDecodeError:
            raise ValueError(f"Inventory for version {version} is not a valid JSON file.")

        for item, digest in version_inventory.items():
            if item not in root_inventory or root_inventory[item] != digest:
                content_digests[item] = digest

    return content_digests

