def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    namaste_file = os.path.join(path, '0=ocfl_1.0')
    if os.path.isfile(namaste_file):
        with open(namaste_file, 'r') as f:
            content = f.read().strip()
            if content == 'ocfl_1.0':
                if os.path.isfile(os.path.join(path, 'inventory.json')):
                    return 'object'
                else:
                    return 'root'
    elif os.path.isdir(path):
        # Check for any OCFL Object indicator
        for item in os.listdir(path):
            if os.path.isdir(os.path.join(path, item)) and item.startswith('v'):
                return 'object'
        return 'root'
    elif os.path.isfile(path):
        return 'file'
    else:
        return 'path does not exist'

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    try:
        if os.path.isfile(path):
            return 'file'

        if not os.path.isdir(path):
            return 'not a directory or file'

        namaste_file = os.path.join(path, '0=ocfl_1.0')
        if os.path.exists(namaste_file):
            return 'root'

        namaste_file = os.path.join(path, 'inventory.json')
        if os.path.exists(namaste_file):
            return 'object'

        namaste_file = os.path.join(path, 'inventory.jsonld')
        if os.path.exists(namaste_file):
            return 'object'

        namaste_file = os.path.join(path, 'inventory.nt')
        if os.path.exists(namaste_file):
            return 'object'

        namaste_file = os.path.join(path, '0=ocfl_object_1.0')
        if os.path.exists(namaste_file):
            return 'object'

        return 'unknown OCFL type'

    except Exception as e:
        return f'error: {str(e)}'

