def parse_arguments(*arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as an ArgumentParser instance.
    '''
    import argparse
    parser = argparse.ArgumentParser(description='Command-line argument parser')
    # Assuming the arguments are provided in the form of '--arg value' or '-a value'
    try:
        for arg in arguments:
            if arg.startswith('--'):
                name, value = arg.split('=')
                parser.add_argument(name, type=str, default=None)
            elif arg.startswith('-'):
                name, value = arg, arguments[arguments.index(arg) + 1]
                parser.add_argument(name, type=str, default=None)
        parsed_args = parser.parse_args(args=list(arguments))
    except Exception as e:
        raise ValueError(f"Error parsing arguments: {e}")
    return parsed_args

