def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    import argparse
    import borgmatic.commands

    def get_parser_actions(parser):
        try:
            actions = parser._actions
        except AttributeError:
            return []
        result = []
        for action in actions:
            if isinstance(action, argparse._SubParsersAction):
                for subaction in action._actions:
                    if isinstance(subaction, argparse._SubParsersAction._ChoicesPseudoAction):
                        result.extend(get_parser_actions(subaction.action))
            else:
                result.append(action)
        return result

    def get_option_strings(action):
        return [option for option in action.option_strings if option.startswith('-')]

    def get_positional_arguments(parser):
        actions = get_parser_actions(parser)
        return [action for action in actions if not action.option_strings]

    def get_optional_arguments(parser):
        actions = get_parser_actions(parser)
        return [action for action in actions if action.option_strings]

    def format_argument(action):
        if isinstance(action, argparse._StoreTrueAction):
            return f" --{action.dest}"
        if isinstance(action, argparse._StoreFalseAction):
            return f" --{action.dest}"
        if action.choices:
            return f" --{action.dest} [{'|'.join(action.choices)}]"
        return f" --{action.dest}=<value>"

    def format_positional(action):
        return f" {action.dest}"

    parsers = []
    borgmatic.commands.generate_subparsers(borgmatic.commands.parse_arguments([]), parsers)

    completions = []
    for action in get_optional_arguments(parsers[0]):
        completions.extend(get_option_strings(action))
    for parser in parsers[1:]:
        for action in get_optional_arguments(parser):
            completions.extend(get_option_strings(action))
        for subparsers_action in get_parser_actions(parsers[0]):
            if isinstance(subparsers_action, argparse._SubParsersAction):
                for subparser in subparsers_action.choices.values():
                    if subparser == parser:
                        completions.append(subparsers_action.dest)

    completion_script = f"_borgmatic() {{
        local cur prev opts
        COMPREPLY=()
        cur=\"{{COMP_WORDS[COMP_CWORD]}}\"
        prev=\"{{COMP_WORDS[COMP_CWORD-1]}}\"
        opts=\"{' '.join(sorted(set(completions)))}\"

        if [[ {{COMP_CWORD}} -eq 1 ]] ; then
            COMPREPLY=( $(compgen -W \"{{opts}}\" -- ${{cur}}) )
            return 0
        fi

        case ${{prev}} in
"
    for parser in parsers[1:]:
        for subparsers_action in get_parser_actions(parsers[0]):
            if isinstance(subparsers_action, argparse._SubParsersAction):
                for subparser_name, subparser in subparsers_action.choices.items():
                    options = []
                    for action in get_optional_arguments(subparser):
                        options.extend(get_option_strings(action))
                    positions = []
                    for action in get_positional_arguments(subparser):
                        positions.append(format_positional(action))
                    completion_script += f"            {subparser_name})\n"
                    completion_script += f"                opts=\"{' '.join(sorted(set(options)))}\"\n"
                    completion_script += f"                COMPREPLY=( $(compgen -W \"{{opts}}\" -- ${{cur}}) )\n"
                    completion_script += f"                return 0\n"
                    completion_script += f"                ;;\n"

    completion_script += "        esac\n"
    completion_script += "    }\n"
    completion_script += "    complete -F _borgmatic borgmatic\n"
    return completion_script

def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    import argparse
    import sys

    def get_parser_actions(parser, actions=None):
        if actions is None:
            actions = []
        for action in parser._actions:
            if isinstance(action, argparse._SubParsersAction):
                for subparser in action.choices.values():
                    get_parser_actions(subparser, actions=actions)
            else:
                actions.append(action)
        return actions

    def escape(value):
        return value.replace('\\', '\\\\').replace('"', '\\"').replace('$', '\\$')

    try:
        import borgmatic.commands.arguments

        parser = borgmatic.commands.arguments.parse_arguments(sys.argv[1:])

        script = ['_borgmatic() {', '    local cur prev opts', '    COMPREPLY=()']
        script.append('    cur="${COMP_WORDS[COMP_CWORD]}"')
        script.append('    prev="${COMP_WORDS[COMP_CWORD-1]}"')
        script.append('    opts="{}"'.format(' '.join(sorted(action.dest for action in get_parser_actions(parser) if action.metavar is None and action.dest is not argparse.SUPPRESS))))

        script.append('    if [[ ${cur} == -* ]] ; then')
        script.append('        COMPREPLY=( $(compgen -W "${opts}" -- ${cur}) )')
        script.append('        return 0')
        script.append('    fi')

        script.append('}')
        script.append('complete -F _borgmatic borgmatic')

        return '\n'.join(script)
    except Exception as e:
        return f"# Error generating bash completion: {escape(str(e))}"

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.upper()
    try:
        if size.endswith('K'):
            return int(size[:-1]) * 1000
        elif size.endswith('M'):
            return int(size[:-1]) * 1000**2
        elif size.endswith('G'):
            return int(size[:-1]) * 1000**3
        elif size.endswith('T'):
            return int(size[:-1]) * 1000**4
        elif size.endswith('P'):
            return int(size[:-1]) * 1000**5
        else:
            return int(size)
    except ValueError:
        raise ValueError(f"Invalid size format: {size}")

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    try:
        size = size.strip()
        suffix = size[-1].upper()
        if suffix in '0123456789':
            return int(size)
        value = int(size[:-1])
        if suffix == 'K':
            return value * 1000
        elif suffix == 'M':
            return value * 1000 * 1000
        elif suffix == 'G':
            return value * 1000 * 1000 * 1000
        elif suffix == 'T':
            return value * 1000 * 1000 * 1000 * 1000
        else:
            raise ValueError(f"Unknown suffix: {suffix}")
    except (ValueError, TypeError) as e:
        raise ValueError(f"Invalid size format: {size}") from e

