def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    def _subclasses(current_cls):
        subclasses_list = current_cls.__subclasses__()
        for subclass in subclasses_list:
            subclasses_list.extend(_subclasses(subclass))
        return subclasses_list

    return _subclasses(cls)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    subclasses_list = []

    def _subclasses_recursively(cls):
        subclasses = cls.__subclasses__()
        subclasses_list.extend(subclasses)
        for subcls in subclasses:
            _subclasses_recursively(subcls)

    _subclasses_recursively(cls)
    return subclasses_list

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet cannot be empty")

    base = len(alphabet)
    result = 0

    for char in string:
        try:
            digit = alphabet.index(char)
        except ValueError:
            raise ValueError(f"Character '{char}' not found in alphabet")

        result = result * base + digit

    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    base = len(alphabet)
    if base == 0:
        raise ValueError("Alphabet must contain at least one character.")

    string_value = 0
    alphabet_index = {char: idx for idx, char in enumerate(alphabet)}

    for char in string:
        if char not in alphabet_index:
            raise ValueError(f"Character '{char}' is not in the provided alphabet.")
        string_value = string_value * base + alphabet_index[char]

    return string_value

def string_to_int(string: str, alphabet: List[str]) -> int:
    """Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not alphabet or not string:
        raise ValueError("Both alphabet and string must be non-empty.")

    base = len(alphabet)
    result = 0

    for index, char in enumerate(string):
        try:
            digit = alphabet.index(char)
        except ValueError:
            raise ValueError(f"Character '{char}' not found in the alphabet.")

        result = result * base + digit

