              0 = Windows/CMD
              (other values reserved)
    """
    import re
    import sys

    if platform == 'this':
        platform = 1 if sys.platform != 'win32' else 0

    if platform == 1:  # POSIX
        regex = r"(?P<quote>['\"])(?P<quoted>.*?)(?P=quote)|(?P<token>[^\s'\"']+)"
    elif platform == 0:  # Windows/CMD
