                # '!!' indicates an ignored file in the git status output
                ignored_files.append(line[3:])  # Ignore the first three characters ('!! ')

        # Sort the list of ignored files
        ignored_files.sort()

        # Join the sorted list into a single string separated by commas
        return ','.join(ignored_files)
    except subprocess.CalledProcessError as e:
        # Handle any errors that occur during the subprocess call
        print(f"Error occurred while running git command: {e}")
        return ""
    except Exception as e:
