def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    try:
        if isinstance(commands, str):
            commands = [commands]

        cmd = commands + args
        if verbose:
            print(f"Running command: {' '.join(cmd)}")

        stderr = subprocess.DEVNULL if hide_stderr else None

        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            capture_output=True,
            text=True,
            stderr=stderr
        )

        if verbose:
            print(f"Command output: {result.stdout}")

        if result.returncode != 0:
            error_message = f"Command failed with return code {result.returncode}"
            if not hide_stderr:
                error_message += f": {result.stderr}"
            raise subprocess.CalledProcessError(result.returncode, cmd, output=result.stdout, stderr=result.stderr)

        return result.stdout

    except Exception as e:
        if verbose:
            print(f"An error occurred: {e}")
        raise

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    try:
        full_command = [commands] + args
        if verbose:
            print(f"Running: {' '.join(full_command)}")
        with subprocess.Popen(full_command, cwd=cwd, env=env, stderr=subprocess.PIPE if hide_stderr else None, stdout=subprocess.PIPE, text=True) as process:
            stdout, stderr = process.communicate()
            if process.returncode != 0:
                error_message = f"Command failed with return code {process.returncode}"
                if stderr:
                    error_message += f": {stderr}"
                raise subprocess.CalledProcessError(process.returncode, full_command, output=stdout, stderr=stderr)
            if verbose and stdout:
                print(stdout)
            return stdout
    except FileNotFoundError:
        raise FileNotFoundError(f"Command not found: {commands}")
    except subprocess.CalledProcessError as e:
        raise e
    except Exception as e:
        raise RuntimeError(f"An error occurred while running the command: {e}")

