    except Exception as e:
        raise RuntimeError(f"An error occurred: {e}") from e

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, list) or not all(isinstance(cmd, str) for cmd in commands):
        raise ValueError("commands must be a list of strings.")

    if not isinstance(args, list) or not all(isinstance(arg, str) for arg in args):
        raise ValueError("args must be a list of strings.")

    full_command = commands + args
    if verbose:
        print("Running command:", ' '.join(full_command))

    stderr = subprocess.STDOUT if hide_stderr else None
    try:
        result = subprocess.run(full_command, cwd=cwd, env=env, capture_output=True, text=True, stderr=stderr, check=True)
        if verbose:
            print("Command output:\n", result.stdout)
        return result.stdout
    except subprocess.CalledProcessError as e:
        if verbose:
            print("Command failed with error:\n", e.stderr)
        raise RuntimeError(f"Command failed with return code {e.returncode}: {e.stderr}") from e
    except Exception as e:
        if verbose:
            print("An unexpected error occurred:", e)
        raise RuntimeError(f"An unexpected error occurred: {e}") from e

