def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if roots is None:
        roots = set()

    for subject, predicate, object in graph:
        if predicate == prop:
            if object not in roots:
                roots.add(object)
            if subject in roots:
                roots.remove(subject)

    return roots

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if roots is None:
        roots = set()

    nodes_with_parents = set()
    for _, parent in graph.subject_objects(prop):
        nodes_with_parents.add(parent)

    for node in graph.subjects():
        if node not in nodes_with_parents:
            roots.add(node)

    return roots

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if roots is None:
        roots = set()

    children = set()
    for child, _, _ in graph.triples((None, prop, None)):
        children.add(child)

    potential_roots = set(graph.subjects()) - children
    for node in potential_roots:
        if node not in children:
            roots.add(node)

    for child, _, parent in graph.triples((None, prop, None)):
        if parent in roots:
            roots.remove(parent)

    return roots

