def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import configparser
    import os

    configs = {}
    log_records = []

    if overrides is None:
        overrides = {}

    for filename in config_filenames:
        config = configparser.ConfigParser()
        try:
            with open(filename, 'r') as config_file:
                config.read_file(config_file)
                if resolve_env:
                    for section in config.sections():
                        for key, value in config.items(section):
                            config.set(section, key, os.path.expandvars(value))
                if filename in overrides:
                    for section, settings in overrides[filename].items():
                        if section not in config:
                            config.add_section(section)
                        for key, value in settings.items():
                            config.set(section, key, value)
                configs[filename] = {section: dict(config.items(section)) for section in config.sections()}
        except (configparser.Error, IOError, OSError) as e:
            log_record = logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0, msg=str(e), args=(), exc_info=True)
            log_records.append(log_record)

    return configs, log_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import configparser
    from os import environ

    if overrides is None:
        overrides = {}

    config_dict = {}
    error_logs = []

    for filename in config_filenames:
        config = configparser.ConfigParser()
        try:
            with open(filename) as f:
                config.read_file(f)
        except Exception as e:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=str(e),
                args=(),
                exc_info=True
            )
            error_logs.append(record)
            continue

        if resolve_env:
            for section in config.sections():
                for key, value in config.items(section):
                    var_match = None
                    if value.startswith('$') and len(value) > 1:
                        var_match = value[1:]
                    elif value.startswith('${') and value.endswith('}') and len(value) > 2:
                        var_match = value[2:-1]
                    if var_match and var_match in environ:
                        config.set(section, key, environ[var_match])

        config_dict[filename] = {section: dict(config.items(section)) for section in config.sections()}

        for section in overrides:
            if section in config_dict[filename]:
                config_dict[filename][section].update(overrides[section])

    return config_dict, error_logs

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import configparser
    import os
    import sys

    config_dict = {}
    log_records = []

    for filename in config_filenames:
        try:
            config = configparser.ConfigParser()
            config.read(filename)

            if overrides:
                for section, options in overrides.items():
                    for option, value in options.items():
                        config.setdefault(section, {})[option] = value

            if resolve_env:
                for section in config.sections():
                    for option in config.options(section):
                        value = config.get(section, option)
                        value = os.path.expandvars(value)
                        config.set(section, option, value)

            config_dict[filename] = {
                section: {option: config.get(section, option) for option in config.options(section)}
                for section in config.sections()
            }

        except Exception as e:
            exc_info = sys.exc_info()
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=str(e),
                args=(),
                exc_info=exc_info
            )
            log_records.append(record)

    return config_dict, log_records

