def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    if other is None:
        if not hasattr(self, '_scale') or self._scale == 0:
            raise LenaValueError("Graph has unknown or zero scale.")
        return self._scale
    else:
        if not isinstance(other, (int, float)):
            raise TypeError("Scale must be a numeric value.")
        if not hasattr(self, '_scale') or self._scale == 0:
            raise LenaValueError("Graph has unknown or zero scale.")
        if len(self.data) == 0:
            raise LenaValueError("Graph has no data to rescale.")

        scale_factor = other / self._scale
        for i in range(len(self.data)):
            try:
                self.data[i][-1] *= scale_factor
                if 'error' in self.data[i]:
                    self.data[i]['error'] *= scale_factor
            except (TypeError, IndexError):
                raise LenaValueError("Graph data is not in the expected format for rescaling.")

        self._scale = other
        return self._scale

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.
    """
    if make_value is None:
        make_value = lambda bin_: bin_

    if get_coordinate not in ["left", "right", "middle"]:
        raise ValueError("get_coordinate must be 'left', 'right', or 'middle'.")

    if len(field_names) != 1 + (1 if isinstance(make_value(bin_.content), tuple) else len(make_value(bin_.content))):
        raise ValueError("Number of field_names must match the dimension of the result.")

    if scale is True:
        scale = hist.scale

    graph = Graph(scale=scale)
    graph.field_names = field_names

    for bin_ in hist:
        if get_coordinate == "left":
            x = bin_.left
        elif get_coordinate == "right":
            x = bin_.right
        elif get_coordinate == "middle":
            x = (bin_.left + bin_.right) / 2

        value = make_value(bin_.content)
        if isinstance(value, tuple):
            point = Point(x, *value)
        else:
            point = Point(x, value)
        graph.add(point)

    return graph

def _verify(iface, candidate, tentative=False, vtype=None):
    from zope.interface.exceptions import Invalid
    import inspect

    errors = []

    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(f"Candidate does not claim to provide the interface {iface}")

    required_methods = {name for name, desc in iface.namesAndDescriptions(all=True)
                        if callable(desc)}

    required_attrs = {name for name, desc in iface.namesAndDescriptions(all=True)
                      if not callable(desc)}

    candidate_methods = {name: method for name, method in inspect.getmembers(candidate, predicate=inspect.ismethod)}

    candidate_attrs = {name: attr for name, attr in inspect.getmembers(candidate, lambda a: not inspect.ismethod(a))}

    for method_name in required_methods:
        if method_name not in candidate_methods:
            errors.append(f"Required method {method_name} is not defined in candidate")
        else:
            candidate_sig = inspect.signature(candidate_methods[method_name])
            iface_sig = inspect.signature(iface[method_name])
            if candidate_sig != iface_sig:
                errors.append(f"Method {method_name} does not have the correct signature. Expected: {iface_sig}, got: {candidate_sig}")

    for attr_name in required_attrs:
        if attr_name not in candidate_attrs:
            errors.append(f"Required attribute {attr_name} is not defined in candidate")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    if not iface or not candidate:
        raise ValueError("Both iface and candidate must be provided.")

    if isinstance(candidate, iface):
        return True

    if tentative:
        return issubclass(candidate, iface)

    return False

