def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    import re

    tags = set()
    code_block = False
    result = []

    # Define a regex pattern for tags and code blocks
    pattern = re.compile(r'(```|`[^`]*`)|(#\w+)')

    for match in re.finditer(pattern, text):
        content = match.group(0)
        if content.startswith('```'):
            code_block = not code_block
            result.append(content)
        elif not code_block:
            if content.startswith('#'):
                tag = content[1:]
                tags.add(tag)
                if replacer:
                    result.append(replacer(content))
                else:
                    result.append(content)
            else:
                result.append(content)
        else:
            result.append(content)

    if not code_block:
        remaining_text = text[match.end():]
        for word in re.findall(r'#\w+', remaining_text):
            tag = word[1:]
            tags.add(tag)
            if replacer:
                remaining_text = remaining_text.replace(word, replacer(word))
        result.append(remaining_text)

    return tags, ''.join(result)

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re

    def linkify(match):
        url = match.group(0)
        return f'<a href="{url}" target="_blank" rel="noopener noreferrer">{url}</a>'

    if not isinstance(text, str):
        raise ValueError("Input must be a string")

    # Simple regex for URLs, this might need more sophisticated handling for all edge cases
    url_pattern = re.compile(
        r'http[s]?://'  # http:// or https://
        r'(?:[a-zA-Z]|[0-9]|[$-_@.&+]|[!*\\(\\),]|'  # domain...
        r'(?:%[0-9a-fA-F][0-9a-fA-F]))+'  # percent-encoded characters
    )

    try:
        processed_text = url_pattern.sub(linkify, text)
    except re.error as e:
        raise RuntimeError("Regex error occurred while processing text links") from e

    return processed_text

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    from urllib.request import Request, urlopen
    from urllib.error import URLError, HTTPError

    try:
        request = Request(url, method='HEAD')
        with urlopen(request) as response:
            return response.getheader('Content-Type')
    except (HTTPError, URLError):
        return None

