    from xml.etree import ElementTree as ET

    try:
        # Try parsing as JSON
        return json.loads(document)
    except json.JSONDecodeError:
        try:
            # Try parsing as XRD (XML)
            root = ET.fromstring(document)
            result = {}
            for element in root.findall('.//'):
                if 'xml:id' in element.attrib:
                    result[element.attrib['xml:id']] = element.text
                else:
                    if element.tag not in result:
                        result[element.tag] = []
                    result[element.tag].append(element.text)
            return result
        except ET.ParseError:
            raise ValueError("The document is neither valid JSON nor valid XRD XML.")
    except Exception as e:
        raise ValueError(f"An error occurred while parsing the document: {str(e)}")

